      if (b % 2 === 0) {
        const notes = [[523.25,659.25,783.99],[587.33,698.46,880],[493.88,587.33,739.99],[440,554.37,659.25]][bar % 4];
        addTone(buffer, sr, t + .025, notes[(b / 2) % 3 | 0], .38, .19, 'sine');
      }
      if (step === 2) addTone(buffer, sr, t, 1450, .04, .035, 'hat');
    }
